/**
 * The state Swift holds for one Erst data directory.
 */
public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * How many deleted videos still wait for their file to be removed.
     *
     * An erase or retention pass that cannot delete a file keeps its path in
     * `pending_unlinks`, and the next `open`, `retention_plan`, or
     * `apply_retention` retries it. The app reports a count above zero so a
     * stuck deletion is visible.
     */
    func pendingFileCount() throws  -> UInt64
    
    /**
     * The version of the Rust core, shown in the app to prove the pipeline links.
     */
    func version()  -> String
    
    /**
     * Opens a segment row and returns its id.
     */
    func beginSegment(relativePath: String, startedAtMs: Int64, width: UInt32, height: UInt32) throws  -> Int64
    
    /**
     * Starts a focus span and returns its id.
     */
    func beginSpan(bundleId: String, appName: String, windowTitle: String?, url: String?, startedAtMs: Int64) throws  -> Int64
    
    /**
     * Closes a focus span.
     */
    func endSpan(spanId: Int64, endedAtMs: Int64) throws 
    
    /**
     * Decides whether a thumbnail is worth keeping and remembers the last kept
     * one. This never touches the database.
     */
    func evaluateFrame(thumbnail: FfiThumbnail, nowMs: Int64, focusChanged: Bool)  -> FfiKeepDecision
    
    /**
     * Marks a segment closed and records its final video size.
     */
    func finishSegment(segmentId: Int64, endedAtMs: Int64, bytes: UInt64) throws 
    
    /**
     * Stores one kept frame, its focus metadata, and its text lines.
     */
    func recordFrame(frame: FfiNewFrame) throws  -> Int64
    
    /**
     * Erases everything recorded in `[start_ms, end_ms)` and reports what was
     * removed.
     *
     * A video cannot be cut, so a segment that overlaps the range is removed
     * whole with every frame it holds. Close the open segment with
     * [`Engine::finish_segment`] before erasing a range that touches it. The
     * next frame after an erase is always kept, even when it looks like an
     * erased one.
     *
     * The erase succeeds once the database change commits. A video that cannot
     * be deleted stays pending and is retried on the next open or retention
     * pass. `purge_complete` is `false` while a reader still holds an old
     * snapshot, so erased text may remain in the write-ahead log until the
     * next erase.
     */
    func erase(startMs: Int64, endMs: Int64) throws  -> FfiEraseResult
    
    /**
     * How `[start_ms, end_ms)` was spent, with the same-length range before it.
     *
     * `time_zone` is an IANA name. Buckets are hours for a range of up to three
     * days and local days after that, each day starting at its own local
     * midnight, so a daylight saving day is 23 or 25 hours long. A range that
     * needs more buckets than the limit is an invalid input error.
     */
    func activity(startMs: Int64, endMs: Int64, timeZone: String) throws  -> FfiActivity
    
    /**
     * Heat for every wall-clock hour of the local days in `[start_ms, end_ms)`,
     * levelled against the busiest hour of the range so the days compare.
     *
     * `time_zone` is an IANA name. Start the range at a local midnight for
     * whole days. A range longer than about 170 days is `InvalidInput`.
     */
    func hourlyHeat(startMs: Int64, endMs: Int64, timeZone: String) throws  -> [FfiDayHeat]
    
    /**
     * Everything the inspector shows for one frame, including its neighbors
     * and how often the same app and window appeared today.
     *
     * `time_zone` anchors "today" for the visit counts.
     */
    func moment(frameId: Int64, timeZone: String) throws  -> FfiMoment
    
    /**
     * The frame closest in time to `at_ms`, earlier on a tie.
     */
    func nearestMoment(atMs: Int64) throws  -> FfiFrameStamp?
    
    /**
     * Searches stored text and returns moments, most recent first.
     *
     * `time_zone` is an IANA name such as `America/New_York` and anchors
     * `today`, `yesterday`, and the date filters. A query with no FTS terms
     * (for example only `app:Safari`) returns no hits.
     */
    func search(query: String, limit: UInt32, timeZone: String) throws  -> [FfiSearchHit]
    
    /**
     * Disk usage and history facts for the storage screen.
     */
    func storage() throws  -> FfiStorage
    
    /**
