/**
 * How a range of time was spent, with the previous range for comparison.
 */
public struct FfiActivity: Equatable, Hashable {
    /**
     * Inclusive range start in Unix milliseconds.
     */
    public var startMs: Int64
    /**
     * Exclusive range end in Unix milliseconds.
     */
    public var endMs: Int64
    /**
     * Clipped milliseconds across all spans.
     */
    public var totalMs: Int64
    /**
     * Total of the same-length range right before, `None` when it had no spans.
     */
    public var previousTotalMs: Int64?
    /**
     * Per category totals in enum order.
     */
    public var categories: [FfiCategoryTotal]
    /**
     * Width of each bucket: one hour, or one local day for a long range.
     */
    public var bucketKind: FfiBucketKind
    /**
     * Consecutive buckets covering `[start_ms, end_ms)`, in time order.
     */
    public var buckets: [FfiBucket]
    /**
     * Per app totals, largest first.
     */
    public var apps: [FfiAppTotal]
    /**
     * Per website host totals, largest first.
     */
    public var websites: [FfiSiteTotal]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Inclusive range start in Unix milliseconds.
         */startMs: Int64, 
        /**
         * Exclusive range end in Unix milliseconds.
         */endMs: Int64, 
        /**
         * Clipped milliseconds across all spans.
         */totalMs: Int64, 
        /**
         * Total of the same-length range right before, `None` when it had no spans.
         */previousTotalMs: Int64?, 
        /**
         * Per category totals in enum order.
         */categories: [FfiCategoryTotal], 
        /**
         * Width of each bucket: one hour, or one local day for a long range.
         */bucketKind: FfiBucketKind, 
        /**
         * Consecutive buckets covering `[start_ms, end_ms)`, in time order.
         */buckets: [FfiBucket], 
        /**
         * Per app totals, largest first.
         */apps: [FfiAppTotal], 
        /**
         * Per website host totals, largest first.
         */websites: [FfiSiteTotal]) {
        self.startMs = startMs
        self.endMs = endMs
        self.totalMs = totalMs
        self.previousTotalMs = previousTotalMs
        self.categories = categories
        self.bucketKind = bucketKind
        self.buckets = buckets
        self.apps = apps
        self.websites = websites
    }

    

    
}

