     * Seconds between captured frames, clamped to `1..=10`.
     */
    public var captureIntervalSeconds: UInt32
    /**
     * Encoder tradeoff.
     */
    public var compression: FfiCompression
    /**
     * Days a segment keeps its original video.
     */
    public var fullQualityDays: UInt32
    /**
     * Months the lighter copy is kept, `None` keeps it forever.
     */
    public var lighterCopyMonths: UInt32?
    /**
     * What happens after the lighter copy period.
     */
    public var afterLighterCopy: FfiAfterLighterCopy
    /**
     * Storage budget in gigabytes, `None` when unlimited.
     */
    public var storageLimitGigabytes: UInt32?
    /**
     * Apps that are never captured.
     */
    public var excludedApps: [FfiAppRef]
    /**
     * How far back agents may read, `None` for all history.
     */
    public var agentHistoryDays: UInt32?

