/**
 * Errors surfaced to Swift as one UniFFI error enum.
 */
public 
enum ErstError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The file system could not be read or written.
     */
    case Io(
        /**
         * Path and operating system message.
         */message: String
    )
    /**
     * The database could not be opened or queried.
     */
    case Database(
        /**
         * The store message.
         */message: String
    )
    /**
     * A caller supplied value is not valid.
     */
    case InvalidInput(
        /**
         * What is wrong with the value.
         */message: String
    )
    /**
     * The requested item does not exist.
     */
    case NotFound(
        /**
         * What was looked up.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

