private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_erst_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_pending_file_count() != 34107) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_version() != 15943) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_begin_segment() != 10824) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_begin_span() != 62348) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_end_span() != 62579) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_evaluate_frame() != 57931) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_finish_segment() != 17200) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_record_frame() != 6000) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_erase() != 54885) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_activity() != 25511) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_hourly_heat() != 52526) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_moment() != 6366) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_nearest_moment() != 46442) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_search() != 63030) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_storage() != 10787) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_timeline() != 32928) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_today_summary() != 49851) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_add_reminder() != 14663) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_complete_reminder() != 55394) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_due_reminders() != 64270) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_erst_ffi_checksum_method_engine_apply_retention() != 39544) {
